{#- Penawaran ke customer, dicetak dari Sales Order -#}

{#-
	Syarat penawarannya diketik di Quotation. Print format ini bisa dipasang di dua doctype:

	- dicetak dari Quotation   -> field-nya dibaca dari dokumen itu sendiri
	- dicetak dari Sales Order -> dibaca dari Quotation asalnya (nomornya nempel di baris item)
-#}
{%- set terms = ["valid_till", "custom_payment_terms", "custom_delivery_point", "custom_delivery_time", "custom_validity", "custom_subject", "custom_your_ref", "custom_sales_name", "owner"] -%}
{%- set quotation = doc.name if doc.doctype == "Quotation" else (doc.items[0].prevdoc_docname if doc.items and doc.items[0].prevdoc_docname else None) -%}
{%- set source = frappe.db.get_value("Quotation", quotation, terms, as_dict=True) if quotation else None -%}
{%- set valid_till = source.valid_till if source else None -%}
{%- set currency = doc.currency -%}
{%- set pt = split_payment_terms((source.custom_payment_terms if source else None) or doc.get("payment_terms_template") or doc.get("tc_name")) -%}
{%- set salutation = frappe.db.get_value("Contact", doc.contact_person, "salutation") if doc.get("contact_person") else None -%}

<style>
	/* kotak Customer, judulnya nempel di garis atas (sama kayak PO / Delivery Order). Dibatesin ke
	   .parties: blok alamat company di kop juga pakai class `box`. */
	.vic-pf .parties { width: 100%; margin-top: 14px; table-layout: fixed; }
	.vic-pf .parties > tbody > tr > td { vertical-align: top; }
	.vic-pf .parties .left { width: 52%; padding-right: 30px !important; }
	.vic-pf .parties .box {
		border: 1px solid #000;
		border-radius: 3px;
		padding: 9px 10px 8px;
		min-height: 70px;
		position: relative;
	}
	.vic-pf .parties .box .cap {
		position: absolute;
		top: -7px;
		left: 9px;
		background: #fff;
		padding: 0 4px;
		font-size: 9px;
	}
	.vic-pf .parties .box .name { font-weight: 700; }
	.vic-pf .qtn-terms { width: 100%; }
	.vic-pf .qtn-terms .lbl { width: 95px; }
	.vic-pf .qtn-terms .sep { width: 12px; }
	/* Your Ref & Subject selebar kolom kiri (kotak Customer), label selebar label kolom kanan - isian
	   yang kepanjangan turun ke baris berikutnya di dalam kolom itu */
	.vic-pf .terms.ref { margin-top: 8px; width: 52%; table-layout: fixed; }
	.vic-pf .terms.ref .lbl { width: 95px; }
	.vic-pf .terms.ref td { overflow-wrap: anywhere; }
	/* gambar logonya punya ruang kosong di atas (~25px setelah diperkecil), jadi dinaikin biar
	   sejajar sama nama & alamat company di sebelahnya */
	.vic-pf .head .logo img { margin-top: -20px; }
</style>

<div class="vic-pf">
	{%- include "vic_addon/templates/print_formats/vic_letterhead.html" -%}

	<div class="title-wrap">
		<div class="title-block">
			<div class="doc-title">QUOTATION</div>
			<table class="meta">
				<tr>
					<td class="lbl">Quotation No.</td>
					<td class="sep">:</td>
					<td>{{ get_print_name(doc) }}</td>
				</tr>
				<tr>
					<td class="lbl">Date</td>
					<td class="sep">:</td>
					<td>{{ frappe.utils.formatdate(doc.transaction_date, "MMMM d, yyyy") }}</td>
				</tr>
			</table>
		</div>
	</div>

	<table class="parties">
		<tr>
			<td class="left">
				<div class="box">
					<span class="cap">Customer</span>
					<div class="name">{{ doc.customer_name or doc.get("customer") or doc.get("party_name") }}</div>
					{%- if doc.contact_display %}<div>{{ [salutation, doc.contact_display] | select | join(" ") }}</div>{% endif %}
				</div>
			</td>
			<td class="right">
				<table class="qtn-terms">
					<tr>
						<td class="lbl">Delivery Point</td>
						<td class="sep">:</td>
						<td>{{ (source.custom_delivery_point if source else None) or doc.get("shipping_address_name") or "" }}</td>
					</tr>
					<tr>
						<td class="lbl">Delivery Time</td>
						<td class="sep">:</td>
						{#- kalau di Quotation-nya dikosongin, jatuh ke teks yang selama ini dipakai di form kertas -#}
						<td>{{ (source.custom_delivery_time if source else None) or "Reconfrom stock before PO" }}</td>
					</tr>
					<tr>
						<td class="lbl">Validity</td>
						<td class="sep">:</td>
						<td>{{ (source.custom_validity if source else None) or (frappe.utils.formatdate(valid_till, "MMMM d, yyyy") if valid_till else "") }}</td>
					</tr>
					<tr>
						<td class="lbl">Payment Terms</td>
						<td class="sep">:</td>
						<td>{{ pt.header }}</td>
					</tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="terms ref">
		<tr>
			<td class="lbl">Your Ref</td>
			<td class="sep">:</td>
			{#- field Your Ref di Quotation duluan; kosong -> PO customer (kalau dicetak dari Sales Order) -#}
			<td>{{ (source.custom_your_ref if source else None) or doc.get("po_no") or "" }}</td>
		</tr>
		<tr>
			<td class="lbl">Subject</td>
			<td class="sep">:</td>
			<td>{{ (source.custom_subject if source else None) or "" }}</td>
		</tr>
	</table>

	<table class="items">
		<thead>
			<tr>
				<th style="width: 7%">Item</th>
				<th class="left" style="width: 43%">Description</th>
				<th style="width: 14%">Qty</th>
				<th style="width: 18%">Unit Price<div>{{ currency }}</div></th>
				<th style="width: 18%">Total Price<div>{{ currency }}</div></th>
			</tr>
		</thead>
		<tbody>
			{%- set ns = namespace(no = 0) %}
			{%- for group in group_items(doc.items) %}
				{#- Pengiriman paling atas, di bawahnya Pengerjaan, terus item - gak ada yang menjorok
				    (lihat vic/item_header.py). Judulnya mulai di kolom Description. -#}
				{%- if group.pengiriman %}
					<tr class="group pengiriman"><td></td><td class="text" colspan="4">{{ group.pengiriman }}</td></tr>
				{%- endif %}
				{%- if group.pengerjaan %}
					<tr class="group"><td></td><td class="text" colspan="4">{{ group.pengerjaan }}</td></tr>
				{%- endif %}
				{%- for item in group.rows %}
					{%- set ns.no = ns.no + 1 %}
					{%- set size = frappe.db.get_value("Item", item.item_code, "custom_size") %}
					{%- set qty = item.qty | float %}
					<tr>
						<td class="num">{{ ns.no }}</td>
						<td class="text">
							<div class="desc">{{ get_item_description(item) }}</div>
							{%- if size %}<div>Size : {{ size }}</div>{% endif %}
						</td>
						<td class="qty">{{ qty | int if qty == qty | round(0) else "%.2f" | format(qty) }} {{ item.uom }}</td>
						<td class="money">{{ frappe.utils.fmt_money(item.rate) }}</td>
						<td class="money">{{ frappe.utils.fmt_money(item.amount) }}</td>
					</tr>
				{%- endfor %}
			{%- endfor %}

			{#- Term pembayaran > 20 karakter: di sini ditulis "Lihat di Note", teks lengkapnya jadi poin pertama
	    Note di akhir tabel item (split_payment_terms di vic/print_utils.py) -#}
			{%- if pt.note %}
				<tr class="note">
					<td></td>
					<td class="text">
						<div>Note:</div>
						<div class="note-item">Payment Terms : {{ pt.note }}</div>
					</td>
					<td colspan="3"></td>
				</tr>
			{%- endif %}
		</tbody>
	</table>

	{#- Ringkasan ngikut formulir: TOTAL PRICE -> DISCOUNT x% -> TOTAL PRICE AFTER DISC -> VAT -> GRAND.
	    Diskon = Total - Net Total, VAT = pajak setelah diskon: angkanya nyambung baik diskon tambahannya
	    dihitung dari Net Total maupun dari Grand Total (di mode Grand Total, pajaknya ikut kepotong). -#}
	{%- set discount = (doc.total | float) - (doc.net_total | float) %}
	{%- set percent = doc.get("additional_discount_percentage") | float %}
	{%- set vat_rows = doc.taxes | rejectattr("is_tax_withholding_account") | selectattr("add_deduct_tax", "ne", "Deduct") | list %}
	{%- set other_rows = doc.taxes | reject("in", vat_rows) | list %}
	{#- WAPU: PPN dipungut pembeli, jadi tabel pajaknya kosong. Kalau Show VAT for WAPU dicentang,
	    VAT 11% tetap dicetak (dihitung dari Net Total) dan ikut dijumlah ke Grand Total di kertas -
	    dokumennya sendiri gak berubah. Kalau ada baris PPN di tabel, yang dipakai tetap baris itu. -#}
	{%- set wapu_vat = frappe.utils.flt((doc.net_total | float) * 0.11, 2) if (doc.get("custom_show_vat_for_wapu") and not vat_rows) else 0 %}
	<table class="totals">
		<tr>
			<td class="lbl">TOTAL PRICE</td>
			<td class="money">{{ frappe.utils.fmt_money(doc.total) }}</td>
		</tr>
		{%- if discount > 0.005 %}
			<tr>
				<td class="lbl">DISCOUNT{% if percent %} {{ "%g" | format(percent) }} %{% endif %}</td>
				<td class="money">{{ frappe.utils.fmt_money(discount) }}</td>
			</tr>
			<tr>
				<td class="lbl">TOTAL PRICE AFTER DISC</td>
				<td class="money">{{ frappe.utils.fmt_money(doc.net_total) }}</td>
			</tr>
		{%- endif %}
		{%- if vat_rows %}
			{%- for tax in vat_rows %}
				<tr>
					<td class="lbl">VAT {{ "%g" | format(tax.rate | float) if tax.rate else 11 }} %</td>
					<td class="money">{{ frappe.utils.fmt_money(tax.tax_amount_after_discount_amount or tax.tax_amount) }}</td>
				</tr>
			{%- endfor %}
		{%- else %}
			<tr>
				<td class="lbl">VAT 11 %</td>
				<td class="money">{{ frappe.utils.fmt_money(wapu_vat) }}</td>
			</tr>
		{%- endif %}
		{%- for tax in other_rows %}
			<tr>
				<td class="lbl">{{ tax.description }}</td>
				<td class="money">{{ frappe.utils.fmt_money(tax.tax_amount_after_discount_amount or tax.tax_amount) }}</td>
			</tr>
		{%- endfor %}
		<tr class="grand">
			<td class="lbl">GRAND TOTAL PRICE</td>
			{#- Rounded Total kalau dipakai (lihat get_grand_total); VAT WAPU ikut dijumlah lalu dibulatin -#}
			<td class="money">{{ frappe.utils.fmt_money(get_grand_total(doc, (doc.grand_total | float) + wapu_vat) if wapu_vat else get_grand_total(doc)) }}</td>
		</tr>
	</table>

	<table class="sign">
		<tr>
			<td style="width: 30%">
				<div class="role">Best regards,</div>
				{#- Sales Name di Quotation (dari SO: Quotation asalnya); kosong -> nama user yang bikin -#}
				{%- set sales_name = (source.custom_sales_name if source else None) or frappe.db.get_value("User", source.owner if source else doc.owner, "full_name") or "" %}
				<div>{{ sales_name | upper }}</div>
			</td>
			<td style="width: 70%"></td>
		</tr>
	</table>
	{%- include "vic_addon/templates/print_formats/vic_footer.html" -%}
</div>
